package com.milktea.security;
import com.milktea.user.entity.NguoiDung; import java.util.Collection; import java.util.List; import org.springframework.security.core.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.UserDetails;
public record UserPrincipal(Long id,String username,String password,boolean active,String role) implements UserDetails { public static UserPrincipal from(NguoiDung u){return new UserPrincipal(u.getId(),u.getTenDangNhap(),u.getMatKhauMaHoa(),u.isDangHoatDong(),u.getVaiTro().getTenVaiTro());} public Collection<? extends GrantedAuthority> getAuthorities(){return List.of(new SimpleGrantedAuthority("ROLE_"+role));} public String getUsername(){return username;} public String getPassword(){return password;} public boolean isAccountNonExpired(){return true;} public boolean isAccountNonLocked(){return active;} public boolean isCredentialsNonExpired(){return true;} public boolean isEnabled(){return active;} }
